using System;using System.IO;using System.Linq;using System.Reflection;using UnityEditor;using UnityEngine;using MashBoxSDK.AnimationStudio;using Object=UnityEngine.Object;
public static class StudioChannelsLayoutValidation {
 static StudioModelEditor editor;static StudioModelDocument doc;static ChannelsWindow window;static double next;static int stage;static string error;static int checks;static readonly BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic;
 static string PathFor(string name)=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../"+name));static void Check(bool ok,string m){if(!ok)throw new Exception(m);checks++;}
 public static void Run(){EditorApplication.delayCall+=Start;}
 static void Start(){try{doc=ScriptableObject.CreateInstance<StudioModelDocument>();var mesh=StudioModelDocument.BuildPrimitive(PrimitiveType.Cube,out var polygons);doc.nodes.Add(new StudioModelDocument.Node{name="Cube",mesh=mesh,cutPolygons=polygons,cutTriangles=mesh.triangles});editor=new StudioModelEditor(()=>window?.Repaint());editor.Load(doc);editor.SelectObject(0);typeof(StudioModelEditor).GetField("transformChannelsExpanded",F).SetValue(editor,true);StudioSettings.Current.theme="graphite";window=ScriptableObject.CreateInstance<ChannelsWindow>();window.position=new Rect(80,80,320,410);window.ShowUtility();next=EditorApplication.timeSinceStartup+1;EditorApplication.update+=Tick;}catch(Exception e){Finish(e.ToString());}}
 static void Tick(){if(EditorApplication.timeSinceStartup<next)return;next=EditorApplication.timeSinceStartup+.4;try{if(error!=null)throw new Exception(error);window.SendEvent(new Event{type=EventType.Layout});window.SendEvent(new Event{type=EventType.Repaint});if(!File.Exists(PathFor("channels-layout-"+stage+".png")))return;if(stage==0){window.position=new Rect(80,80,450,410);}else if(stage==1){StudioSettings.Current.theme="porcelain";}else if(stage==2){typeof(StudioModelEditor).GetField("transformChannelsExpanded",F).SetValue(editor,false);}else{window.SendEvent(new Event{type=EventType.MouseDown,button=0,mousePosition=new Vector2(18,42)});window.SendEvent(new Event{type=EventType.MouseUp,button=0,mousePosition=new Vector2(18,42)});Check(!editor.Document.nodes[0].active&&!editor.Transforms[0].gameObject.activeSelf,"Name-row checkbox hides selected object even with Transform collapsed");editor.PerformWorkspaceHistory(false);Check(editor.Document.nodes[0].active&&editor.Transforms[0].gameObject.activeSelf,"Visibility checkbox undo restores object");editor.PerformWorkspaceHistory(true);Check(!editor.Document.nodes[0].active,"Visibility checkbox redo restores hidden state");window.SendEvent(new Event{type=EventType.MouseDown,button=0,mousePosition=new Vector2(65,68)});window.SendEvent(new Event{type=EventType.MouseUp,button=0,mousePosition=new Vector2(65,68)});Check((bool)typeof(StudioModelEditor).GetField("transformChannelsExpanded",F).GetValue(editor),"Transform header click expands rows");Check(StudioPreferenceStore.GetFloat("Model.TransformChannelsExpanded",0)==1,"Transform expansion saved through preference store");using(var reload=new StudioModelEditor(()=>{}))Check((bool)typeof(StudioModelEditor).GetField("transformChannelsExpanded",F).GetValue(reload),"Transform expansion reloads");Check(editor.Document.nodes[0].position==Vector3.zero&&editor.Document.nodes[0].scale==Vector3.one,"Painting layout does not edit transforms");Finish("PASS "+checks+" rendered channels layout checks");return;}stage++;window.Repaint();}catch(Exception e){Finish(e.ToString());}}
 public sealed class ChannelsWindow:EditorWindow{
  void OnGUI(){bool paint=Event.current.type==EventType.Repaint;RenderTexture rt=null;var old=RenderTexture.active;if(paint){rt=new RenderTexture((int)position.width,(int)position.height,0,RenderTextureFormat.ARGB32);rt.Create();RenderTexture.active=rt;GL.PushMatrix();GL.Clear(false,true,Color.clear);GL.LoadPixelMatrix(0,position.width,position.height,0);}try{using(StudioTheme.Scope()){EditorGUI.DrawRect(new Rect(0,0,position.width,position.height),StudioTheme.Current.Panel);GUILayout.BeginArea(new Rect(0,0,position.width,position.height));editor.DrawInspector();GUILayout.EndArea();if(paint){Check(EditorStyles.numberField.border.left==3,"Rounded numeric field has slice border");var tex=EditorStyles.numberField.normal.background;Check(tex&&tex.width==10&&tex.GetPixel(0,0).a<.3f&&tex.GetPixel(5,5).a>.99f,"Field background has transparent corners and opaque center");}}if(paint){var image=new Texture2D(rt.width,rt.height,TextureFormat.RGBA32,false);image.ReadPixels(new Rect(0,0,rt.width,rt.height),0,0);image.Apply();Check(image.GetPixels32().Count(c=>c.a>0)>10000,"Native UI renders pixels");File.WriteAllBytes(PathFor("channels-layout-"+stage+".png"),image.EncodeToPNG());Object.DestroyImmediate(image);}}catch(Exception e){error=e.ToString();}finally{if(paint){GL.PopMatrix();RenderTexture.active=old;Object.DestroyImmediate(rt);}}}
 }
 static void Finish(string result){EditorApplication.update-=Tick;File.WriteAllText(PathFor("channels-layout-result.txt"),result);EditorApplication.Exit(result.StartsWith("PASS")?0:1);}
}
